<template>
  <div class="bank-page">
    <header class="page-head"><div><span class="eyebrow">NGÂN HÀNG GIẢNG VIÊN</span><h1>Ngân hàng câu hỏi</h1><p>Quản lý câu hỏi riêng của bạn để dùng lại khi tạo đề. Chỉnh sửa ở đây không làm thay đổi đề thi đã tạo.</p></div><div class="head-actions"><button class="button secondary" @click="openImport">Nhập Excel / Word / PDF</button><button class="button primary" @click="openCreate">+ Thêm câu hỏi</button></div></header>
    <div v-if="error" class="notice error" role="alert">{{ error }}</div><div v-if="success" class="notice success" role="status">{{ success }}</div>
    <section class="filters"><input v-model="filters.q" type="search" placeholder="Tìm trong nội dung câu hỏi" @input="scheduleLoad"/><select v-model="filters.chu_de" @change="loadQuestions"><option value="">Tất cả chủ đề</option><option v-for="topic in topics" :key="topic" :value="topic">{{topic}}</option></select><select v-model="filters.loai_cau_hoi" @change="loadQuestions"><option value="">Tất cả loại</option><option value="trac_nghiem">Trắc nghiệm</option><option value="tu_luan">Tự luận</option></select><select v-model="filters.do_kho" @change="loadQuestions"><option value="">Mọi độ khó</option><option value="de">Dễ</option><option value="trung_binh">Trung bình</option><option value="kho">Khó</option></select><select v-model="filters.trang_thai" @change="loadQuestions"><option value="">Mọi trạng thái</option><option value="active">Đang sử dụng</option><option value="inactive">Đã vô hiệu hóa</option></select></section>
    <section class="question-list"><div v-if="loading" class="empty">Đang tải câu hỏi…</div><div v-else-if="!items.length" class="empty">Chưa có câu hỏi phù hợp với bộ lọc.</div><template v-else><article v-for="item in items" :key="item.id" class="question-card"><div class="card-top"><div class="badges"><span class="badge">{{item.loai_cau_hoi === 'trac_nghiem' ? 'Trắc nghiệm' : 'Tự luận'}}</span><span class="badge difficulty" :class="item.do_kho">{{difficultyLabel(item.do_kho)}}</span><span v-if="item.chu_de" class="badge topic">{{item.chu_de}}</span></div><span class="status" :class="item.trang_thai">{{item.trang_thai === 'active' ? 'Đang sử dụng' : 'Đã vô hiệu hóa'}}</span></div><h2>{{item.noi_dung}}</h2><ol v-if="item.loai_cau_hoi === 'trac_nghiem'" class="answers"><li v-for="(answer,index) in item.dap_an" :key="answer.id" :class="{correct:answer.la_dap_an_dung}"><b>{{letter(index)}}.</b> {{answer.noi_dung}} <span v-if="answer.la_dap_an_dung">· Đáp án đúng</span></li></ol><div v-else class="essay-meta">Điểm mặc định {{item.diem_tu_luan}} · Có hướng dẫn chấm</div><div class="card-actions"><button class="text-button" @click="openEdit(item)">Chỉnh sửa</button><button class="text-button" @click="duplicate(item)">Nhân bản</button><button v-if="item.trang_thai==='active'" class="text-button danger-text" @click="deactivate(item)">Vô hiệu hóa</button></div></article></template><footer v-if="meta.total" class="pagination"><span>{{meta.total}} câu hỏi</span><button class="button secondary" :disabled="page<=1" @click="changePage(-1)">Trước</button><span>Trang {{page}} / {{meta.last_page}}</span><button class="button secondary" :disabled="page>=meta.last_page" @click="changePage(1)">Sau</button></footer></section>
    <div v-if="showEditor" class="modal-backdrop" @click.self="closeEditor"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="editor-title"><header><div><span class="eyebrow">{{editing?'CẬP NHẬT NGÂN HÀNG':'THÊM VÀO NGÂN HÀNG'}}</span><h2 id="editor-title">{{editing?'Chỉnh sửa câu hỏi':'Câu hỏi mới'}}</h2></div><button class="close" aria-label="Đóng" @click="closeEditor">×</button></header><form @submit.prevent="saveQuestion"><label>Nội dung câu hỏi<textarea v-model="form.noi_dung" rows="4" maxlength="10000" required/></label><div class="form-grid"><label>Loại câu hỏi<select v-model="form.loai_cau_hoi"><option value="trac_nghiem">Trắc nghiệm</option><option value="tu_luan">Tự luận</option></select></label><label>Chủ đề<input v-model="form.chu_de" maxlength="120" placeholder="Ví dụ: Mạng máy tính"/></label><label>Độ khó<select v-model="form.do_kho"><option value="de">Dễ</option><option value="trung_binh">Trung bình</option><option value="kho">Khó</option></select></label></div><template v-if="form.loai_cau_hoi==='trac_nghiem'"><div class="answer-heading">Phương án — chọn một đáp án đúng</div><div v-for="(answer,index) in form.dap_an" :key="index" class="answer-edit"><input v-model="form.dap_an[index]" :aria-label="`Phương án ${letter(index)}`" required maxlength="5000"/><label class="correct-choice"><input v-model.number="form.dap_an_dung_index" type="radio" name="correct-answer" :value="index"/> Đúng</label><button type="button" class="icon-button" :disabled="form.dap_an.length<=2" @click="removeAnswer(index)">×</button></div><button type="button" class="text-button" :disabled="form.dap_an.length>=6" @click="form.dap_an.push('')">+ Thêm phương án</button></template><template v-else><div class="form-grid"><label>Điểm mặc định<input v-model="form.diem_tu_luan" type="number" min="0.01" max="10" step="0.01" required/></label></div><label>Đáp án mẫu / hướng dẫn chấm<textarea v-model="form.dap_an_mau" rows="4" maxlength="20000" required/></label></template><div v-if="formError" class="notice error">{{formError}}</div><footer class="modal-actions"><button type="button" class="button secondary" @click="closeEditor">Hủy</button><button class="button primary" :disabled="saving">{{saving?'Đang lưu…':'Lưu câu hỏi'}}</button></footer></form></section></div>
    <div v-if="showImporter" class="modal-backdrop" @click.self="closeImport"><section class="modal import-modal" role="dialog" aria-modal="true" aria-labelledby="import-title"><header><div><span class="eyebrow">NHẬP CÂU HỎI</span><h2 id="import-title">Xem trước trước khi lưu</h2></div><button class="close" aria-label="Đóng" @click="closeImport">×</button></header><div v-if="!importRows.length"><p>Chấp nhận .xlsx, .docx, .pdf tối đa 10 MB theo mẫu import hiện tại.</p><input type="file" accept=".xlsx,.docx,.pdf" @change="previewImport"/><p v-if="importError" class="notice error">{{importError}}</p></div><div v-else><div class="form-grid"><label>Chủ đề áp dụng<input v-model="importMeta.chu_de" maxlength="120"/></label><label>Độ khó mặc định<select v-model="importMeta.do_kho"><option value="de">Dễ</option><option value="trung_binh">Trung bình</option><option value="kho">Khó</option></select></label></div><div class="preview-list"><article v-for="(row,index) in importRows" :key="index"><b>{{index+1}}. {{row.loai_cau_hoi==='tu_luan'?'Tự luận':'Trắc nghiệm'}}</b><p>{{row.noi_dung}}</p><small>{{row.loai_cau_hoi==='tu_luan'?'Điểm '+row.diem+' · '+(row.dap_an_mau?'Có hướng dẫn chấm':'Thiếu hướng dẫn chấm'):(row.dap_an?.length||0)+' phương án'}}</small></article></div><p v-if="importError" class="notice error">{{importError}}</p><footer class="modal-actions"><button class="button secondary" @click="importRows=[]">Chọn file khác</button><button class="button primary" :disabled="saving" @click="saveImport">{{saving?'Đang lưu…':`Lưu ${importRows.length} câu`}}</button></footer></div></section></div>
  </div>
</template>

<script setup>
import { onBeforeUnmount, onMounted, reactive, ref } from 'vue'
import api from '../../../services/api'
const items=ref([]),topics=ref([]),loading=ref(false),saving=ref(false),error=ref(''),success=ref(''),formError=ref(''),importError=ref(''),page=ref(1),meta=reactive({total:0,last_page:1}),filters=reactive({q:'',chu_de:'',loai_cau_hoi:'',do_kho:'',trang_thai:''}),showEditor=ref(false),showImporter=ref(false),editing=ref(null),importRows=ref([]),importMeta=reactive({chu_de:'',do_kho:'trung_binh'});const emptyForm=()=>({noi_dung:'',loai_cau_hoi:'trac_nghiem',chu_de:'',do_kho:'trung_binh',diem_tu_luan:'',dap_an_mau:'',dap_an:['',''],dap_an_dung_index:0});const form=reactive(emptyForm());let searchTimer;const letter=i=>String.fromCharCode(65+i);const difficultyLabel=v=>({de:'Dễ',trung_binh:'Trung bình',kho:'Khó'})[v]||v
async function loadQuestions(){loading.value=true;error.value='';try{const{data}=await api.get('/giang-vien/ngan-hang-cau-hoi',{params:{...filters,page:page.value}});items.value=data.data||[];topics.value=data.meta?.topics||[];meta.total=data.meta?.total||0;meta.last_page=data.meta?.last_page||1}catch(e){error.value=e.response?.data?.message||'Không tải được ngân hàng câu hỏi.'}finally{loading.value=false}}
function scheduleLoad(){clearTimeout(searchTimer);page.value=1;searchTimer=setTimeout(loadQuestions,250)}function changePage(n){page.value+=n;loadQuestions()}function resetForm(){Object.assign(form,emptyForm());formError.value=''}function openCreate(){editing.value=null;resetForm();showEditor.value=true}function openEdit(item){editing.value=item.id;formError.value='';Object.assign(form,{noi_dung:item.noi_dung,loai_cau_hoi:item.loai_cau_hoi,chu_de:item.chu_de||'',do_kho:item.do_kho,diem_tu_luan:item.diem_tu_luan||'',dap_an_mau:item.dap_an_mau||'',dap_an:item.dap_an.map(a=>a.noi_dung),dap_an_dung_index:item.dap_an.findIndex(a=>a.la_dap_an_dung)});showEditor.value=true}function removeAnswer(i){form.dap_an.splice(i,1);if(form.dap_an_dung_index===i)form.dap_an_dung_index=-1;else if(form.dap_an_dung_index>i)form.dap_an_dung_index--}function closeEditor(){showEditor.value=false}
async function saveQuestion(){saving.value=true;formError.value='';const wasEditing=Boolean(editing.value);try{const payload={...form};if(payload.loai_cau_hoi==='tu_luan'){payload.dap_an=[];payload.dap_an_dung_index=null}if(editing.value)await api.put(`/giang-vien/ngan-hang-cau-hoi/${editing.value}`,payload);else await api.post('/giang-vien/ngan-hang-cau-hoi',payload);closeEditor();success.value=wasEditing?'Đã cập nhật câu hỏi.':'Đã thêm câu hỏi.';await loadQuestions()}catch(e){formError.value=Object.values(e.response?.data?.errors||{}).flat()[0]||e.response?.data?.message||'Không lưu được câu hỏi.'}finally{saving.value=false}}
async function duplicate(item){try{await api.post(`/giang-vien/ngan-hang-cau-hoi/${item.id}/duplicate`);success.value='Đã nhân bản câu hỏi.';await loadQuestions()}catch(e){error.value=e.response?.data?.message||'Không nhân bản được câu hỏi.'}}async function deactivate(item){if(!window.confirm('Vô hiệu hóa câu hỏi này? Câu hỏi không bị xóa.'))return;try{await api.patch(`/giang-vien/ngan-hang-cau-hoi/${item.id}/deactivate`);success.value='Đã vô hiệu hóa câu hỏi.';await loadQuestions()}catch(e){error.value=e.response?.data?.message||'Không vô hiệu hóa được câu hỏi.'}}
function openImport(){importRows.value=[];importError.value='';importMeta.chu_de='';importMeta.do_kho='trung_binh';showImporter.value=true}function closeImport(){showImporter.value=false;importRows.value=[]}async function previewImport(e){const file=e.target.files?.[0];if(!file)return;importError.value='';const body=new FormData();body.append('file',file);try{const{data}=await api.post('/giang-vien/ngan-hang-cau-hoi/import-preview',body);importRows.value=data.data||[]}catch(err){importError.value=err.response?.data?.message||'Không đọc được file import.'}}async function saveImport(){saving.value=true;importError.value='';try{await api.post('/giang-vien/ngan-hang-cau-hoi/import-save',{questions:importRows.value,...importMeta});closeImport();success.value='Đã nhập câu hỏi vào ngân hàng.';await loadQuestions()}catch(e){importError.value=Object.values(e.response?.data?.errors||{}).flat()[0]||e.response?.data?.message||'Không lưu được câu hỏi đã nhập.'}finally{saving.value=false}}
onMounted(loadQuestions);onBeforeUnmount(()=>clearTimeout(searchTimer))
</script>

<style scoped>
.bank-page{max-width:1280px;margin:auto;padding:24px;color:#172033}.page-head{display:flex;justify-content:space-between;gap:24px;align-items:center;margin-bottom:22px}.eyebrow{font-size:.72rem;letter-spacing:.12em;font-weight:800;color:#5673a5}.page-head h1{margin:5px 0;font-size:clamp(1.7rem,3vw,2.3rem)}.page-head p{margin:0;color:#65718a;max-width:760px}.head-actions{display:flex;gap:10px;flex-wrap:wrap}.button{border:0;border-radius:9px;padding:10px 15px;font-weight:700;cursor:pointer}.button:disabled{opacity:.5;cursor:default}.primary{background:#2563eb;color:white}.secondary{background:#eaf0f8;color:#22304a}.filters{display:grid;grid-template-columns:minmax(220px,2fr) repeat(4,minmax(130px,1fr));gap:10px;margin-bottom:18px}.filters input,.filters select,.modal input:not([type=radio]),.modal select,.modal textarea{width:100%;border:1px solid #d5ddeb;border-radius:8px;padding:10px 11px;background:white;color:#172033}.question-list{display:grid;gap:12px}.question-card{background:white;border:1px solid #e0e6ef;border-radius:13px;padding:18px 20px;box-shadow:0 3px 12px #1d35570a}.card-top{display:flex;justify-content:space-between;gap:12px;align-items:center}.badges{display:flex;gap:7px;flex-wrap:wrap}.badge,.status{padding:4px 9px;border-radius:999px;font-size:.78rem;font-weight:700;background:#eef3fa;color:#45546e}.badge.difficulty.de{background:#e6f7ee;color:#187447}.badge.difficulty.trung_binh{background:#fff4dc;color:#90630b}.badge.difficulty.kho{background:#ffebe8;color:#a33c32}.badge.topic{background:#eaf0ff;color:#3f59a4}.status.active{background:#e6f7ee;color:#187447}.status.inactive{background:#f0f1f4;color:#6b7280}.question-card h2{font-size:1.05rem;line-height:1.55;margin:15px 0}.answers{padding-left:24px;margin:0;color:#45546e}.answers li{padding:4px 0}.answers .correct{color:#187447}.essay-meta{color:#56627a;background:#f7f9fc;padding:10px;border-radius:8px}.card-actions{display:flex;gap:16px;border-top:1px solid #edf0f5;margin-top:15px;padding-top:12px}.text-button{border:0;background:none;color:#2563eb;font-weight:700;cursor:pointer;padding:3px}.text-button:disabled{opacity:.5}.danger-text{color:#b63832}.empty{text-align:center;padding:50px 20px;background:#fff;border:1px dashed #ccd5e2;border-radius:12px;color:#65718a}.pagination{display:flex;align-items:center;justify-content:center;gap:14px;padding:16px;color:#65718a}.notice{padding:11px 14px;border-radius:9px;margin:10px 0}.notice.error{background:#fff0ef;color:#a42b22}.notice.success{background:#eaf8ef;color:#176a3b}.modal-backdrop{position:fixed;inset:0;z-index:1000;background:#11182799;display:grid;place-items:center;padding:18px}.modal{width:min(760px,100%);max-height:92vh;overflow:auto;background:white;border-radius:16px;padding:22px;box-shadow:0 18px 70px #10182855}.modal header{display:flex;justify-content:space-between;align-items:flex-start;margin-bottom:18px}.modal h2{margin:4px 0}.close,.icon-button{border:0;background:#edf1f7;border-radius:8px;width:34px;height:34px;font-size:22px;cursor:pointer}.modal form{display:grid;gap:14px}.modal form>label,.modal label{display:grid;gap:7px;font-size:.9rem;font-weight:700;color:#38455c}.form-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:12px}.answer-heading{font-weight:700}.answer-edit{display:grid;grid-template-columns:1fr auto 34px;gap:10px;align-items:center}.correct-choice{display:flex!important;align-items:center;gap:6px!important;white-space:nowrap}.modal-actions{display:flex;justify-content:flex-end;gap:10px;margin-top:8px}.import-modal{width:min(820px,100%)}.preview-list{max-height:45vh;overflow:auto;display:grid;gap:8px;margin:14px 0}.preview-list article{border:1px solid #e2e7ef;border-radius:9px;padding:11px}.preview-list p{margin:5px 0}.preview-list small{color:#667085}@media(max-width:800px){.page-head{align-items:flex-start;flex-direction:column}.filters{grid-template-columns:1fr 1fr}.filters input{grid-column:1/-1}.form-grid{grid-template-columns:1fr 1fr}}@media(max-width:520px){.bank-page{padding:14px}.filters,.form-grid{grid-template-columns:1fr}.answer-edit{grid-template-columns:1fr auto}.answer-edit input:first-child{grid-column:1/-1}.card-top{align-items:flex-start;flex-direction:column}.pagination{gap:7px;flex-wrap:wrap}}
</style>
